cd /tmp/probe/outputs/work/fmt && python3 - <<'EOF'
import struct,zlib
d=open('cfgtrans.png','rb').read(); i=8; idat=b''
while i<len(d):
    ln=struct.unpack('>I',d[i:i+4])[0]; typ=d[i+4:i+8]
    if typ==b'IDAT': idat+=d[i+8:i+8+ln]
    if typ==b'IHDR': w,h,bd,ct,_,_,_=struct.unpack('>IIBBBBB',d[i+8:i+8+ln])
    i+=12+ln
raw=zlib.decompress(idat); stride=w*4
out=bytearray(); p=0
for y in range(h):
    p+=1; line=bytearray(raw[p:p+stride]); p+=stride
    for x in range(4,stride): line[x]=(line[x]+line[x-4])&255
    out+=line
def px(x,y):
    o=(y*w+x)*4; return tuple(out[o:o+4])
print("corner a=0:",px(0,0))
# find a pixel with alpha ~128
seen={}
for y in range(h):
    for x in range(w):
        a=px(x,y)[3]
        if 20<a<240 and a not in seen: seen[a]=(x,y,px(x,y))
for a in sorted(seen)[:6]+sorted(seen)[-4:]:
    print("alpha",a,"->",seen[a])
# center of window
print("window interior:",px(259,120))
EOF
